export const BODY: string = "\n<p>ضبط التباين يستغرق بضع دقائق فقط. ترفع الصورة وتسحب منزلقًا وتراجع الأضواء والظلال وتنزّل النسخة الأقوى.</p>\n<p>هذا البرنامج التعليمي يمر بالعملية كاملة خطوة بخطوة. يغطي المنزلق والإعدادات السريعة وأوضاع المقارنة وضبط التصدير التي تبقي النتيجة بمظهر طبيعي.</p>\n<p>في النهاية ستستطيع إصلاح مشهد مسطح أو تلطيف صورة شخصية قاسية أو ضبط لقطة شاشة باهتة على أي جهاز. واحتفظ بالصورة الأصلية حتى تراجع النتيجة.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: شخّص الصورة</h2>\n<p>انظر إلى الصورة قبل فتح الأداة. هل هي مسطحة ورمادية أم قاسية بظلال عميقة أم بسعة صحيحة؟ الجواب يخبرك بأي اتجاه تحرك المنزلق.</p>\n<p>صورة مسطحة تحتاج دفعة موجبة 10 إلى 20 بالمئة. صورة قاسية تحتاج حركة سالبة 10 إلى 20 بالمئة لتلطيف الطرفين. وراجع إن كانت الصورة داكنة جدًا أو فاتحة جدًا أيضًا: صورة داكنة ومسطحة تحتاج سطوعًا أولًا، لأن التباين وحده لا يستطيع إصلاح المستوى.</p>\n<p>افتح <a href=\"/ar/taadil-tabayun-as-sura/\">محرر تباين الصور</a> في متصفحك. كل شيء يعمل محليًا، فصورتك لا تُرفع أبدًا إلى خادم.</p>\n<h2 id=\"step-by-step\">اضبط التباين في خمس خطوات</h2>\n<p>العملية نفسها لصورة أو لقطة شاشة أو مستند ممسوح ضوئيًا. ارفع الصورة واضبط وقارن وصدّر وتحقق من التنزيل.</p>\n<p>خذ وقتك مع المنزلق. الحركات الصغيرة تصنع فرقًا كبيرًا، والمعاينة تُظهر لك بالضبط متى تبدو الصورة جيدة. وافتح الملف المنزّل مرة قبل استخدامه، وتأكد من أن الصورة تبدو قوية دون فقدان تفاصيل في المناطق الفاتحة أو الداكنة.</p>\n<ol>\n<li>ارفع صورتك بسحبها إلى منطقة الرفع أو اختيارها من جهازك أو لصق لقطة شاشة بـCtrl+V.</li>\n<li>اسحب منزلق مستوى التباين إلى اليمين لزيادة التباين أو إلى اليسار لتقليله، مراقبًا المعاينة الحية.</li>\n<li>جرّب إعدادًا سريعًا لاختبار بنقرة واحدة، ثم دقّق بالمنزلق إن كانت النتيجة قريبة لكنها ليست جيدة تمامًا.</li>\n<li>استخدم أوضاع المقارنة لمراجعة الأضواء والظلال مقابل الأصل قبل التنزيل.</li>\n<li>اختر صيغة التصدير والجودة، ثم اضغط تنزيل لحفظ الصورة المعدلة.</li>\n</ol>\n<h2 id=\"using-the-slider\">كيف تستخدم منزلق التباين</h2>\n<p>يتراوح المنزلق من قيم سالبة إلى موجبة، مع الصفر كلا تغيير. تحريكه إلى اليمين يزيد التباين، وتحريكه إلى اليسار يقلله.</p>\n<p>اسحب ببطء وراقب المعاينة. التحديث الحي يُظهر بالضبط كيف تستجيب الصورة، فتستطيع التوقف عند النقطة التي تبدو فيها الصورة جيدة. والحركات الصغيرة أفضل من الكبيرة: تغيير 10 إلى 20 بالمئة غالبًا يكفي، والحركات الأكبر تقص الأضواء وتسحق الظلال بسرعة.</p>\n<p>تُظهر الأداة صورتك بـ+20 بالمئة فور رفعها. نقطة البداية هذه تعطيك فكرة فورية عن مظهر زيادة تباين معتدلة.</p>\n<h2 id=\"using-quick-presets\">كيف تستخدم الإعدادات السريعة</h2>\n<p>تضم الأداة إعدادات سريعة تطبق قيم تباين شائعة بنقرة واحدة. إنها طريقة سريعة لتجربة مستويات مختلفة دون سحب المنزلق.</p>\n<p>اضغط إعدادًا سريعًا وراقب المعاينة. إذا كانت النتيجة قريبة لكنها ليست جيدة تمامًا، دقّق بالمنزلق من تلك النقطة. واستخدم الإعدادات السريعة لمقارنة الخيارات بسرعة: إعداد +10 بالمئة بجانب إعداد +30 بالمئة يُظهر كم تباين تتحمل الصورة.</p>\n<p>ولدفعة صور متشابهة، نفس الإعداد السريع يبقي النتائج متسقة. مجموعة مشاهد ضبابية، كلها معززة بنفس القدر، تبدو كسلسلة.</p>\n<h2 id=\"using-compare-modes\">كيف تستخدم أوضاع المقارنة</h2>\n<p>أوضاع المقارنة تُظهر الأصل والنسخة المعدلة معًا. عرض بعد يُظهر الصورة بتباين أكثر، وعرض قبل يُظهر الأصل.</p>\n<p>المقارنة المقسومة هي الأكثر فائدة للعمل على التباين. تُظهر النسختين جنبًا إلى جنب، لتستطيع رؤية أي ظلال تعمّقت وأي أضواء افتّحت بالضبط. والمقارنة بملء الشاشة تعطي أكبر عرض: إنها أفضل طريقة للحكم على تعديل تباين، لأن الصورة بالحجم الكامل تُظهر قصًا تخفيه معاينة صغيرة.</p>\n<p>راجع عرض المقارنة قبل كل تنزيل. نظرة سريعة تكتشف أضواء مقصوصة وظلال مسحوقة قد تخفيها معاينة صغيرة.</p>\n<h2 id=\"boosting-a-flat-photo\">كيف تعزز صورة مسطحة</h2>\n<p>ارفع الصورة المسطحة واسحب المنزلق إلى +15 بالمئة. راجع المعاينة: يجب أن تتعمق الظلال وأن تفتّح الأضواء وأن تشعر الصورة بالصلابة.</p>\n<p>إذا بقيت الصورة مسطحة، زد المنزلق بخطوات صغيرة 5 بالمئة. كل خطوة تضيف قليلًا من القوة، والمعاينة تُظهر متى تتوقف. وراقب الأضواء وأنت تتقدم: الغيوم والقمصان البيضاء والبشرة الفاتحة ستُقص أولًا، لتصبح بقعًا بيضاء بلا ملامح.</p>\n<p>إذا بدت الصورة قاسية بعد تعزيزها، اخفض المنزلق 5 بالمئة. تخفيض صغير غالبًا يستعيد التفاصيل دون إعادة تسطيح الصورة.</p>\n<h2 id=\"softening-a-harsh-photo\">كيف تلطّف صورة قاسية</h2>\n<p>اسحب المنزلق إلى اليسار لصورة التُقطت بشمس ظهر قاسية. قيم سالبة مثل -10 أو -20 بالمئة تلطّف الظلال القوية على وجه.</p>\n<p>راجع الوجه وأنت تلطّف: يجب أن تتلاشى الظلال إلى مظهر أنعم، بينما يبقى الشكل العام للوجه واضحًا ومحددًا. والتباين السالب يناسب أيضًا المشاهد الناعمة والحالمة: مشهد ضبابي صباحي بتباين قليل يشعر بالهدوء والصمت، ما يناسب مزاج الصورة.</p>\n<p>لا تبالغ: صورة بتباين قليل جدًا تبدو رمادية وبلا حياة، كأنها التُقطت عبر ضباب، حتى في يوم صافٍ.</p>\n<h2 id=\"fixing-a-screenshot\">كيف تصلح لقطة شاشة باهتة</h2>\n<p>الصق لقطة شاشة مباشرة بـCtrl+V لتتخطى خطوة الحفظ. تظهر الصورة في المحرر فورًا، جاهزة للضبط.</p>\n<p>زد التباين حتى يكون النص داكنًا والخلفية بيضاء. مستند بنص أسود قوي فوق خلفية بيضاء نظيفة سهل القراءة والطباعة. وراقب الضجيج في الخلفية: مسح بتباين كبير قد يُظهر بقعًا وشوائب، خصوصًا في JPEG مضغوط مسبقًا.</p>\n<p>صدّر اللقطات كـPNG. الصيغة دون فقدان تبقي النص الصغير حادًا، وهو أمر مهم عندما تُظهر اللقطة ضبطًا أو رسالة خطأ.</p>\n<h2 id=\"checking-shadows-highlights\">كيف تراجع الظلال والأضواء</h2>\n<p>بعد كل تغيير تباين، راجع أشد أجزاء الصورة ظلامًا وأشدها سطوعًا منفصلة. الظلال تُسحق أولًا مع دفعة، والأضواء تُقص أولًا مع نفس الدفعة.</p>\n<p>قرّب على منطقة ظل وتأكد أنها ما زالت تُظهر تفاصيل: معطف أو شجرة أو زاوية داكنة يجب أن يكون لها قوام مرئي، لا بقعة سوداء صلبة. وقرّب على منطقة فاتحة وتأكد أنها ما زالت تُظهر تفاصيل: غيمة أو قميص أبيض أو جبهة ساطعة يجب أن يكون لها شكل مرئي، لا بياض فارغ.</p>\n<p>إذا فقد أي طرف تفاصيل، اخفض المنزلق 5 بالمئة وراجع مجددًا: التخفيضات الصغيرة غالبًا تستعيد التفاصيل دون فقدان القوة.</p>\n<h2 id=\"previewing\">المعاينة قبل التنزيل</h2>\n<p>راجع المعاينة دائمًا قبل التنزيل. تحقق من أن الصورة تبدو قوية، وأن لا منطقة فاتحة أصبحت بيضاء، وأن لا منطقة داكنة أصبحت سوداء.</p>\n<p>استخدم عرض المقارنة المقسومة لمراجعة التغيير: يُظهر الأصل والنسخة المعدلة جنبًا إلى جنب، لتستطيع رؤية ما فعله التباين بالضبط. وقرّب على المناطق الفاتحة والداكنة بالحجم الكامل: سماء أو ظل يبدو جيدًا في معاينة صغيرة قد يكون مقصوصًا أو مسحوقًا عند رؤيته كبيرًا.</p>\n<p>إذا بدت النتيجة قاسية، اخفض المنزلق 5 بالمئة وراجع مجددًا: التخفيضات الصغيرة غالبًا تستعيد التفاصيل دون إعادة تسطيح الصورة.</p>\n<h2 id=\"choosing-export-format\">كيف تختار صيغة التصدير</h2>\n<p>اختر JPG للصور التي تنوي مشاركتها. يبقي الملفات صغيرة ويعمل في كل مكان، وضبط جودة عالية يبقي الصورة المعدلة بالتباين نظيفة.</p>\n<p>اختر PNG للقطات الشاشة والرسوم ذات النص. لا يفقد PNG شيئًا، فتبقى حواف الحروف حادة، ويحافظ على الشفافية عندما تحتاجها. واختر WebP عندما تريد ملفات صغيرة بجودة جيدة: يعمل جيدًا لصور الويب، مع أن بعض الأنظمة القديمة ما زالت ترفض الصيغة.</p>\n<p>تذكر أن ضبط الجودة يُخفى لـPNG، لأن PNG دون فقدان وليس له ضبط جودة لتغييره. هذا سلوك طبيعي، لا مشكلة في الأداة.</p>\n<h2 id=\"adjusting-on-mobile\">كيف تضبط التباين على الهاتف أو الجهاز اللوحي</h2>\n<p>تعمل الأداة على شاشات اللمس، فتستطيع إصلاح صورة مسطحة على الهاتف نفسه الذي التقطها. ارفع الصورة من معرضك واسحب المنزلق بإصبعك ونزّل النتيجة.</p>\n<p>سحب منزلق بالإصبع أقل دقة من الفأرة: استخدم الإعدادات السريعة لقيم دقيقة، ثم دقّق بسحبات صغيرة. وراجع المعاينة بالحجم الكامل قبل التنزيل: تغيير تباين يبدو جيدًا على شاشة هاتف صغيرة قد يكون قويًا جدًا عند رؤيته على حاسوب.</p>\n<p>تُحفظ الملفات المنزّلة في مجلد التنزيلات المعتاد لديك. ومن هناك يمكنك مشاركة الصورة المعدلة مباشرة إلى تطبيق محادثة أو بريد أو منشور اجتماعي.</p>\n<h2 id=\"troubleshooting\">كيف تحل مشاكل التباين الشائعة</h2>\n<p>إذا بدت الصورة قاسية، فالمنزلق مرتفع جدًا. اخفضه بخطوات صغيرة حتى تُظهر البشرة والسماء ومناطق الظل قوامًا مجددًا.</p>\n<p>وإذا بقيت الصورة مسطحة بعد تعزيزها، فقد يكون الأصل ضبابيًا جدًا لإنقاذه: صورة التُقطت عبر ضباب كثيف لا تستطيع اكتساب تفاصيل لم تُسجل أبدًا. وإذا كانت الأضواء مقصوصة، اخفض المنزلق وراجع المناطق الفاتحة بالحجم الكامل: تخفيض صغير غالبًا يستعيد تفاصيل الغيوم أو البشرة.</p>\n<p>وإذا بدت المعاينة مختلفة عن التنزيل، راجع صيغة التصدير والجودة: ضبط جودة JPG منخفض قد ينعّم الصورة كلها، بما فيها حواف التباين.</p>\n<h2 id=\"contrast-plus-brightness\">تباين مع سطوع: الثنائي الشائع</h2>\n<p>صورة داكنة ومسطحة تحتاج سطوعًا وتباينًا معًا. فتّح أولًا لرفع المستوى العام، ثم أضف تباينًا لاستعادة العمق.</p>\n<p>استخدم <a href=\"/ar/taadil-sutoo-as-sura/\">محرر سطوع الصورة</a> قبل إضافة تباين، عندما تكون الصورة داكنة: دفعة تباين على صورة داكنة تعمّق الظلال فقط. واعمل الخطوات بالترتيب: سطوع أولًا ثم تباين. عكسهما قد يجعل الحكم على ضبط التباين أصعب، لأن الصورة ما زالت داكنة.</p>\n<p>راجع عرض المقارنة بعد كل خطوة: العرض المقسوم يُظهر بالضبط ما فعله كل ضبط، فتستطيع التوقف عندما تبدو الصورة جيدة.</p>\n<h2 id=\"saving-settings\">كيف تحفظ ضبطك للمرة القادمة</h2>\n<p>دوّن قيمة التباين التي نجحت لمجموعة صور متشابهة. ملاحظة قصيرة، مثل مشاهد ضبابية +20 بالمئة، توفر عليك التخمين في المرة القادمة.</p>\n<p>ولدفعة صور التُقطت بنفس الضوء، استخدم نفس القيمة لكلها: تباين متسق عبر مجموعة يبدو احترافيًا، بينما القيم المختلطة تبدو عشوائية. واحتفظ بالملفات الأصلية: قيمة تباين تناسب صورة قد لا تناسب أخرى، والأصل يتيح لك تجربة مستوى مختلف دون ضرر إضافي.</p>\n<p>راجع ملاحظاتك من حين لآخر. مع تحسن كاميرتك وإضاءتك، ستتغير قيم التباين التي تحتاجها، وقد تضللك الملاحظات القديمة.</p>\n<h2 id=\"quick-tips\">نصائح سريعة لتباين أفضل</h2>\n<p>اضبط بخطوات صغيرة. تغيير 5 بالمئة في كل مرة يمنحك تحكمًا، بينما قفزة كبيرة قد تتجاوز القيمة الصحيحة قبل أن تلاحظ.</p>\n<p>راجع الطرفين، لا الوسط فقط: صورة بها تباين زائد عندما تُقص الأضواء أو تُسحق الظلال، حتى لو بدت النغمات الوسطى جيدة. واستخدم عرض المقارنة دائمًا: نظرة سريعة إلى الأصل بجانب التعديل تكتشف أخطاء تخفيها معاينة صغيرة.</p>\n<p>احفظ الصورة الأصلية دون تعديل. بمجرد أن يُدمج تغيير تباين في تصدير، لا يمكن التراجع عنه من ذلك الملف.</p>\n<h2 id=\"contrast-for-product-photo\">كيف تضيف تباينًا إلى صورة منتج</h2>\n<p>صور المنتج تحتاج تباينًا واضحًا ليبرز العنصر عن الخلفية. صورة منتج مسطحة تبدو باهتة، بينما صورة قوية تجذب النظر إلى العنصر.</p>\n<p>استخدم دفعة معتدلة 10 إلى 20 بالمئة لمعظم المنتجات: يجب أن يبدو العنصر صلبًا ومحددًا، بحواف واضحة مقابل الخلفية. وراقب ألوان المنتج وأنت تزيد التباين: دفعة قوية جدًا قد تجعل الألوان تبدو قاسية، فراجع العنصر نفسه لا الخلفية فقط.</p>\n<p>أبقِ التباين متسقًا عبر الكتالوج كله: متجر بمستويات تباين متطابقة يبدو مرتبًا وموثوقًا، بينما المستويات المختلطة تبدو مهملة.</p>\n<p>للمقارنة، اقرأ <a href=\"/ar/blog/sutoo-vs-taarid-vs-tabayun/\">سطوع أم تعريض أم تباين: أساسيات التعديل</a>. وللدليل الكامل، راجع <a href=\"/ar/blog/dalil-muharrir-tabayun-as-suwar/\">دليل محرر تباين الصور الكامل</a>، ولإصلاح صورة داكنة قبل ضبط التباين استخدم <a href=\"/ar/taadil-sutoo-as-sura/\">محرر سطوع الصورة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أضيف تباينًا إلى صورة على هاتفي؟","answer":"افتح محرر تباين الصور في متصفح هاتفك وارفع الصورة من معرضك واسحب المنزلق إلى اليمين بإصبعك. واستخدم إعدادًا سريعًا لقيمة دقيقة، وراجع عرض المقارنة ونزّل النتيجة."},{"question":"أي قيمة تباين يجب أن أستخدم لمشهد ضبابي؟","answer":"ابدأ بـ+15 إلى +20 بالمئة وراجع السماء. الضباب يسطّح النطاق النغمي، فدفعة معتدلة تستعيد العمق. وتوقف قبل أن تصبح الغيوم بياضًا فارغًا، واخفض المنزلق إن قُصت الأضواء."},{"question":"هل يمكنني تقليل التباين لتلطيف صورة شخصية قاسية؟","answer":"نعم، اسحب المنزلق إلى اليسار نحو قيم سالبة، مثل -10 أو -20 بالمئة. التباين السالب يلطّف الظلال القوية على الوجه دون فقدان شكله. وراجع البشرة لتبقى محددة وطبيعية."},{"question":"لماذا تصبح أضواء صورتي بيضاء بعد إضافة تباين؟","answer":"دُفع التباين بعيدًا جدًا، ما قص أشد المناطق سطوعًا إلى أبيض خالص. اخفض المنزلق بخطوات صغيرة حتى تُظهر الغيوم والبشرة والأسطح البيضاء تفاصيل مجددًا. ودفعة 10 إلى 20 بالمئة تكفي غالبًا."},{"question":"هل أضبط التباين قبل السطوع أم بعده؟","answer":"السطوع أولًا ثم التباين. السطوع يثبت المستوى العام، والتباين يضبط السعة حول ذلك المستوى. وصورة داكنة تحتاج تفتيحًا قبل التباين، إذ لا يستطيع التباين وحده إصلاح مستوى داكن."},{"question":"هل يمكنني التراجع عن تغيير تباين بعد التنزيل؟","answer":"لا من الملف المنزّل، إذ يُدمج التغيير في التصدير. احتفظ بالصورة الأصلية لتستطيع تجربة مستوى تباين آخر. وفي الأداة، استخدم خيار إعادة الضبط للعودة إلى الصفر قبل التنزيل."}];
